// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));

        address originalOwner = c.owner();
        assertTrue(originalOwner == address(this));

        bool ok;
        if (caller == address(this)) {
            try c.transferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(ok);
            assertTrue(c.owner() == newOwner);
        } else {
            vm.prank(caller);
            try c.transferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(!ok);
        }
    }
}
